policies.inbound:


  __AUDIENCES__

<set-variable name="denial" value="@{
  if (context.Request.Method != "POST" || context.Request.Body == null) { return ""; }
  var body = context.Request.Body.As(preserveContent: true);
  if ((string)body["method"] != "tools/call") { return ""; }
  var claims = ((Jwt)context.Variables["jwt"]).Claims;
  var roles = claims.ContainsKey("roles") ? claims["roles"] : new string[0];
  var categories = new [] { "general", "world", "nation", "business", "technology", "entertainment", "sports", "science", "health" };
  var allowed = roles.Contains("News.Read.All") ? categories : categories.Where(c => roles.Contains("News.Read." + char.ToUpper(c[0]) + c.Substring(1))).ToArray();
  var name = (string)body["params"]["name"];
  var arguments = body["params"]["arguments"] as JObject;
  var category = (arguments == null ? null : (string)arguments["category"]) ?? "general";
  var permitted = name == "top_headlines" ? allowed.Contains(category) : name == "search" ? roles.Contains("News.Read.All") : true;
  if (permitted) { return ""; }
  if (allowed.Length == 0) { return "Your access covers no news categories. Do not retry."; }
  return "Your access covers: " + string.Join(", ", allowed) + ". Do not retry other categories.";
}" />





        application/json

      @(new JObject(
        new JProperty("jsonrpc", "2.0"),
        new JProperty("id", context.Request.Body.As(preserveContent: true)["id"]),
        new JProperty("result", new JObject(
          new JProperty("content", new JArray(new JObject(
            new JProperty("type", "text"),
            new JProperty("text", (string)context.Variables["denial"])))),
          new JProperty("isError", true)))).ToString())





  {{gnews-api-key}}
